 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (1, 2):
                points[value] = (r, c)
    (r1, c1), (r2, c2) = points[1], points[2]
    dr = 1 if r2 > r1 else -1
    dc = 1 if c2 > c1 else -1
    nr, nc = abs(r2-r1), abs(c2-c1)
    # Follow a diagonal toward the second marker, then continue along
    # the remaining axis; the marker cells themselves are preserved.
    for k in range(1, min(nr, nc) + 1):
        r, c = r1 + dr*k, c1 + dc*k
        if (r, c) != (r2, c2):
            out[r][c] = 3
    r, c = r1 + dr*min(nr, nc), c1 + dc*min(nr, nc)
    if nr > nc:
        for k in range(1, nr-nc + 1):
            rr = r + dr*k
            if (rr, c) != (r2, c2):
                out[rr][c] = 3
    elif nc > nr:
        for k in range(1, nc-nr + 1):
            cc = c + dc*k
            if (r, cc) != (r2, c2):
                out[r][cc] = 3
    return out
